+#!/usr/bin/env python3
+"""Optional batch preflight and composition audit (stdlib only).
+
+  python3 -I batch_audit.py --catalog CATALOG.csv --id ID_COL --batch BATCH.csv \
+        [--prior R1_results.csv R2_results.csv ...] --rows N [--col COLNAME] [--factors c1,c2,...]
+
+Preflight (hard FAIL, exit 1): row count, single required column name, duplicate IDs,
+IDs missing from the catalogue, IDs already ordered in --prior files, stray whitespace,
+index column.
+
+Audit (information only): for each factor column in --factors, how many batch picks share each
+level, the largest share, and which levels have never been ordered before (prior files) --
+this shows concentration on one dominant level and levels still untested.
+The factor columns must exist in the catalogue; if --factors is omitted, every catalogue column
+other than the ID column is audited (high-cardinality columns are skipped).
+"""
+import argparse
+import csv
+import sys
+from collections import Counter
+
+
+def read(path):
+    with open(path, newline="") as f:
+        return list(csv.reader(f))
+
+
+def main():
+    ap = argparse.ArgumentParser()
+    ap.add_argument("--catalog", required=True)
+    ap.add_argument("--id", required=True, help="ID column name in the catalogue (also the batch column)")
+    ap.add_argument("--batch", required=True)
+    ap.add_argument("--prior", nargs="*", default=[])
+    ap.add_argument("--rows", type=int, required=True)
+    ap.add_argument("--col", default=None, help="required batch column name (default: same as --id)")
+    ap.add_argument("--factors", default=None)
+    a = ap.parse_args()
+    col = a.col or a.id
+    fail = []
+
+    cat = read(a.catalog)
+    chead, crows = cat[0], cat[1:]
+    if a.id not in chead:
+        sys.exit(f"ID column {a.id!r} not in catalogue header {chead}")
+    ci = chead.index(a.id)
+    cat_ids = {r[ci] for r in crows}
+    by_id = {r[ci]: r for r in crows}
+
+    raw = read(a.batch)
+    bhead, brows = raw[0], raw[1:]
+    if bhead != [col]:
+        fail.append(f"header is {bhead}, expected exactly [{col!r}] (no index column)")
+    ids = [r[0] if r else "" for r in brows]
+    if len(ids) != a.rows:
+        fail.append(f"{len(ids)} rows, expected {a.rows}")
+    if any(len(r) != 1 for r in brows):
+        fail.append("some rows do not have exactly one field")
+    if any(i != i.strip() or not i for i in ids):
+        fail.append("empty ID or extra whitespace in some IDs")
+    dup = [k for k, v in Counter(ids).items() if v > 1]
+    if dup:
+        fail.append(f"duplicate IDs: {dup[:5]}")
+    missing = [i for i in ids if i not in cat_ids]
+    if missing:
+        fail.append(f"{len(missing)} IDs not in catalogue, e.g. {missing[:5]}")
+
+    prior_ids = set()
+    for p in a.prior:
+        pr = read(p)
+        ph = pr[0]
+        pc = ph.index(a.id) if a.id in ph else 0
+        prior_ids |= {r[pc] for r in pr[1:] if r}
+    again = [i for i in ids if i in prior_ids]
+    if again:
+        fail.append(f"{len(again)} IDs already ordered earlier, e.g. {again[:5]}")
+
+    print(f"rows={len(ids)} unique={len(set(ids))} in_catalog={len(ids) - len(missing)} "
+          f"already_ordered={len(again)} prior_ids={len(prior_ids)}")
+
+    factors = a.factors.split(",") if a.factors else [
+        h for h in chead if h != a.id and len({r[chead.index(h)] for r in crows}) <= 60]
+    for f in factors:
+        if f not in chead:
+            print(f"(skip unknown factor {f!r})")
+            continue
+        fi = chead.index(f)
+        picked = Counter(by_id[i][fi] for i in ids if i in by_id)
+        seen_before = {by_id[i][fi] for i in prior_ids if i in by_id}
+        levels = sorted({r[fi] for r in crows})
+        untested = [l for l in levels if l not in seen_before and picked.get(l, 0) == 0]
+        top = picked.most_common(1)[0] if picked else ("-", 0)
+        print(f"[{f}] levels={len(levels)} largest_share={top[1]}/{len(ids)} ({top[0]}) "
+              f"untested_after_this_batch={len(untested)}")
+        print("   picks: " + ", ".join(f"{k}:{v}" for k, v in picked.most_common(12)))
+        if untested and len(untested) <= 12:
+            print("   untested: " + ", ".join(untested))
+
+    if fail:
+        for m in fail:
+            print("FAIL: " + m)
+        sys.exit(1)
+    print("PREFLIGHT OK")
+
+
+if __name__ == "__main__":
+    main()
