+#!/usr/bin/env node
+// Optional pre-delivery check for a final_model.js. Loads plain-function files (a bare
+// `function predict(...)`) as well as module.exports / exports.predict styles, without edits.
+//
+// Usage:
+//   node check_model.js <final_model.js> <inputs.txt> [--topk N] [--expect expected.tsv]
+//
+//   inputs.txt    one predict() input string per line (every catalogue entry plus training entries)
+//   expected.tsv  optional "input<TAB>value" lines from your fitting code; reports the largest
+//                 absolute difference against the JS output (porting errors are silent otherwise)
+//
+// Hard failures (exit 1): cannot load/find predict, non-finite output, outputs that differ between
+// two identical runs, outputs that depend on call order, constant output, --expect mismatch > 1e-6.
+// Everything else (source scan, resolution, tie blocks, top list) is reported for judgement only.
+const fs = require('fs');
+const path = require('path');
+const vm = require('vm');
+
+const args = process.argv.slice(2);
+const pos = [];
+let topk = 20;
+let expectPath = null;
+for (let i = 0; i < args.length; i++) {
+  if (args[i] === '--topk') topk = parseInt(args[++i], 10);
+  else if (args[i] === '--expect') expectPath = args[++i];
+  else pos.push(args[i]);
+}
+if (pos.length < 2) {
+  console.error('usage: node check_model.js <final_model.js> <inputs.txt> [--topk N] [--expect expected.tsv]');
+  process.exit(2);
+}
+const [modelPath, inputsPath] = pos;
+let fail = 0;
+const bad = (m) => { console.log('FAIL: ' + m); fail = 1; };
+
+const src = fs.readFileSync(path.resolve(modelPath), 'utf8');
+
+// Source scan: things the task format usually forbids. Judgement only.
+const banned = [
+  [/\brequire\s*\(/, 'require()'], [/\bimport\s/, 'import'], [/Math\.random/, 'Math.random'],
+  [/Date\.now|new Date/, 'clock'], [/\bprocess\./, 'process'], [/\bfetch\s*\(/, 'fetch'],
+  [/readFileSync|readFile\b/, 'file read'],
+];
+const hits = banned.filter(([re]) => re.test(src)).map(([, n]) => n);
+if (hits.length) console.log('WARN: source mentions ' + hits.join(', ') + ' (check the model format rules)');
+
+// Load in an isolated context. Top-level function declarations become properties of the sandbox.
+const mod = { exports: {} };
+const sandbox = { module: mod, exports: mod.exports, console: { log() {}, error() {}, warn() {} } };
+vm.createContext(sandbox);
+try {
+  new vm.Script(src, { filename: modelPath }).runInContext(sandbox, { timeout: 10000 });
+} catch (e) {
+  bad('could not load file: ' + e.message);
+  process.exit(1);
+}
+let predict = null;
+const ex = mod.exports;
+if (ex && typeof ex.predict === 'function') predict = ex.predict;
+else if (typeof ex === 'function') predict = ex;
+else if (ex && ex.default && typeof ex.default.predict === 'function') predict = ex.default.predict;
+else if (typeof sandbox.predict === 'function') predict = sandbox.predict;
+if (!predict) {
+  bad('no predict function found (looked at module.exports.predict, module.exports, and a top-level function)');
+  process.exit(1);
+}
+
+const lines = fs.readFileSync(inputsPath, 'utf8').split('\n').map((s) => s.trim()).filter(Boolean);
+const uniq = Array.from(new Set(lines));
+const run = (arr) => arr.map((s) => {
+  try { return predict(s); } catch (e) { return NaN; }
+});
+
+const a = run(uniq);
+const b = run(uniq);
+const nonFinite = a.filter((v) => typeof v !== 'number' || !Number.isFinite(v)).length;
+if (nonFinite) bad(`${nonFinite} non-finite outputs or exceptions`);
+if (a.some((v, i) => v !== b[i])) bad('outputs differ between two identical runs');
+
+// fixed-seed LCG shuffle: this tool needs no randomness source either
+let seed = 12345;
+const rnd = () => (seed = (seed * 1664525 + 1013904223) % 4294967296) / 4294967296;
+const idx = uniq.map((_, i) => i);
+for (let i = idx.length - 1; i > 0; i--) {
+  const j = Math.floor(rnd() * (i + 1));
+  [idx[i], idx[j]] = [idx[j], idx[i]];
+}
+const c = run(idx.map((i) => uniq[i]));
+if (idx.some((orig, k) => c[k] !== a[orig])) bad('outputs depend on call order');
+
+const distinct = new Set(a).size;
+console.log(`inputs=${a.length} distinct_scores=${distinct} (${(100 * distinct / Math.max(1, a.length)).toFixed(1)}%)`);
+if (distinct <= 1) bad('constant predictions');
+
+// tie blocks with their rank positions (rank 1 = highest score)
+const order = a.map((v, i) => [v, i]).sort((x, y) => y[0] - x[0]);
+const blocks = [];
+for (let r = 0; r < order.length;) {
+  let e = r;
+  while (e + 1 < order.length && order[e + 1][0] === order[r][0]) e++;
+  if (e > r) blocks.push({ score: order[r][0], size: e - r + 1, first: r + 1, last: e + 1 });
+  r = e + 1;
+}
+blocks.sort((x, y) => y.size - x.size);
+if (blocks.length) {
+  console.log('largest tie blocks:');
+  blocks.slice(0, 3).forEach((t) => console.log(
+    `  ${t.size} tied at ranks ${t.first}-${t.last} (${(100 * t.first / a.length).toFixed(0)}%-${(100 * t.last / a.length).toFixed(0)}% down the list), score ${t.score}`));
+  const top = blocks.filter((t) => t.first <= topk);
+  if (top.length) console.log(`NOTE: ${top.length} tie block(s) touch the top ${topk}; evaluation order would decide their relative rank.`);
+} else {
+  console.log('no tied scores');
+}
+
+if (expectPath) {
+  const exp = new Map();
+  fs.readFileSync(expectPath, 'utf8').split('\n').forEach((l) => {
+    const t = l.split('\t');
+    if (t.length >= 2 && t[0].trim() && Number.isFinite(parseFloat(t[1]))) exp.set(t[0].trim(), parseFloat(t[1]));
+  });
+  let maxd = 0, n = 0;
+  uniq.forEach((s, i) => { if (exp.has(s)) { n++; maxd = Math.max(maxd, Math.abs(exp.get(s) - a[i])); } });
+  console.log(`expect: compared ${n} inputs, max abs diff ${maxd.toExponential(2)}`);
+  if (n === 0) console.log('WARN: no --expect inputs matched the inputs file');
+  if (maxd > 1e-6) bad('JS output differs from the fitting code beyond 1e-6 (check parsing, rounding, unseen levels)');
+}
+
+console.log(`top-${topk}:`);
+order.slice(0, topk).forEach(([v, i]) => console.log(`  ${Number.isFinite(v) ? v.toPrecision(5) : v}  ${uniq[i]}`));
+console.log(fail ? 'RESULT: FAIL' : 'RESULT: OK (source scan, resolution and top list above are for judgement)');
+process.exit(fail);
